import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and tracks quantity", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks separate products independently", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity to 0 removes the product", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
      "Product nonexistent is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes correct subtotal", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount policy to subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
    });
    cart.add(productA, 10); // subtotal = 10000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000);
  });

  it("clamps discount to subtotal (never negative discounted subtotal)", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBeGreaterThanOrEqual(0);
  });

  it("clamps negative discount to 0", () => {
    const negativeDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negativeDiscount });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal, not raw subtotal", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn((taxable: number, _region: string) =>
        Math.floor(taxable * 0.1),
      ),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      taxCalculator: taxCalc,
    });
    cart.add(productA, 10); // subtotal 10000, discount 2000, discounted 8000
    const totals = cart.totals();
    expect(totals.taxCents).toBe(800); // 10% of 8000
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(8000, "US");
  });

  it("passes region to tax calculator", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("clamps negative tax to 0", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const shippingCalc: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      shippingCalculator: shippingCalc,
    });
    cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
    cart.totals();
    expect(shippingCalc.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalc: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: shippingCalc });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
    });
    cart.add(productA, 10); // subtotal 10000
    const totals = cart.totals();
    // discount: 10% of 10000 = 1000; discounted = 9000
    expect(totals.discountCents).toBe(1000);
    // tax: 8% of 9000 = 720
    expect(totals.taxCents).toBe(720);
    // shipping: 500
    expect(totals.shippingCents).toBe(500);
    // total: 9000 + 720 + 500 = 10220
    expect(totals.totalCents).toBe(10220);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, US region", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });
});

describe("Cart — async checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("passes inventory check when available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when available is false", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("generates default reason when none is provided", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.message).toContain("insufficient stock");
      expect(err.message).toContain("a");
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US-CA",
    });
    cart.add(productA, 10); // subtotal 10000, discount 1000, discounted 9000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(9000 * 0.0875) = floor(787.5) = 787
    expect(result.totals.taxCents).toBe(787);
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(9000 + 787 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("combines all collaborators: price refresh + inventory + async tax", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      shippingCalculator: new FlatShippingCalculator(200),
    });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(500)   // productA new price
        .mockResolvedValueOnce(1000), // productB new price
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal = 500*2 + 1000*1 = 2000, no discount, tax = floor(2000*0.05) = 100, shipping = 200
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(0);
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.shippingCents).toBe(200);
    expect(result.totals.totalCents).toBe(2300);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("first inventory denial wins when multiple products fail", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.add(productB, 3);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "product A denied" })
        .mockResolvedValueOnce({ available: false, reason: "product B denied" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      // First denial wins
      expect((e as InventoryError).message).toBe("product A denied");
      // Only first product checked
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    }
  });

  it("checkout does not mutate the cart's internal lines", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9999),
    };
    await cart.checkout({ priceFetcher });
    // Cart still has original price
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 99999])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  it("computes 10% of 1000 = 100", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(1000)).toBe(100);
  });

  it("rounds down to nearest cent", () => {
    const policy = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 exactly
    expect(policy.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor → 33
    expect(policy.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-1000)).toBe(0);
  });

  it("100% discount equals subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(5000)).toBe(5000);
  });

  it("0% discount returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps at subtotal when fixed amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(300)).toBe(300);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("order does not affect sum result", () => {
      const a = new PercentageDiscountPolicy(10);
      const b = new FixedAmountDiscountPolicy(200);
      const ab = new CompositeDiscountPolicy([a, b], "sum");
      const ba = new CompositeDiscountPolicy([b, a], "sum");
      expect(ab.computeDiscountCents(1000)).toBe(ba.computeDiscountCents(1000));
    });

    it("can produce total exceeding subtotal (cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each returns min(600, 1000) = 600, sum = 1200 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100, remaining 900; 10% of 900 = 90; total = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order affects chain result", () => {
      const a = new FixedAmountDiscountPolicy(200);
      const b = new PercentageDiscountPolicy(50);
      const ab = new CompositeDiscountPolicy([a, b], "chain");
      const ba = new CompositeDiscountPolicy([b, a], "chain");
      // ab: fixed 200 off 1000 → remaining 800; 50% of 800 = 400; total = 600
      expect(ab.computeDiscountCents(1000)).toBe(600);
      // ba: 50% of 1000 = 500 → remaining 500; fixed 200 off 500 → 200; total = 700
      expect(ba.computeDiscountCents(1000)).toBe(700);
    });

    it("never exceeds subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // first: min(800, 1000) = 800, remaining 200; second: min(800, 200) = 200; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: 100 + 200 = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

