    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity to 0 removes the product", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
      "Product nonexistent is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes correct subtotal", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount policy to subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
    });
    cart.add(productA, 10); // subtotal = 10000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000);
  });

  it("clamps discount to subtotal (never negative discounted subtotal)", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBeGreaterThanOrEqual(0);
  });

  it("clamps negative discount to 0", () => {
    const negativeDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negativeDiscount });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal, not raw subtotal", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn((taxable: number, _region: string) =>
        Math.floor(taxable * 0.1),
      ),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      taxCalculator: taxCalc,
    });
    cart.add(productA, 10); // subtotal 10000, discount 2000, discounted 8000
    const totals = cart.totals();
    expect(totals.taxCents).toBe(800); // 10% of 8000
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(8000, "US");
  });

  it("passes region to tax calculator", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("clamps negative tax to 0", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const shippingCalc: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      shippingCalculator: shippingCalc,
    });
    cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
    cart.totals();
    expect(shippingCalc.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalc: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: shippingCalc });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
    });
    cart.add(productA, 10); // subtotal 10000
    const totals = cart.totals();
    // discount: 10% of 10000 = 1000; discounted = 9000
    expect(totals.discountCents).toBe(1000);
    // tax: 8% of 9000 = 720
    expect(totals.taxCents).toBe(720);
    // shipping: 500
    expect(totals.shippingCents).toBe(500);
    // total: 9000 + 720 + 500 = 10220
    expect(totals.totalCents).toBe(10220);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, US region", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });
});

describe("Cart — async checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("passes inventory check when available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when available is false", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("generates default reason when none is provided", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.message).toContain("insufficient stock");
      expect(err.message).toContain("a");
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US-CA",
    });
    cart.add(productA, 10); // subtotal 10000, discount 1000, discounted 9000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax = floor(9000 * 0.0875) = floor(787.5) = 787
    expect(result.totals.taxCents).toBe(787);
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(9000 + 787 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("combines all collaborators: price refresh + inventory + async tax", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      shippingCalculator: new FlatShippingCalculator(200),
    });
    cart.add(productA, 2);
    cart.add(productB, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(500)   // productA new price
        .mockResolvedValueOnce(1000), // productB new price
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // subtotal = 500*2 + 1000*1 = 2000, no discount, tax = floor(2000*0.05) = 100, shipping = 200
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(0);
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.shippingCents).toBe(200);
    expect(result.totals.totalCents).toBe(2300);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("first inventory denial wins when multiple products fail", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.add(productB, 3);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "product A denied" })
        .mockResolvedValueOnce({ available: false, reason: "product B denied" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      // First denial wins
      expect((e as InventoryError).message).toBe("product A denied");
      // Only first product checked
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    }
  });

  it("checkout does not mutate the cart's internal lines", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9999),
    };
    await cart.checkout({ priceFetcher });
    // Cart still has original price
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});
"}

