+    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
+  });
+
+  it("returns 0 when subtotal exceeds freeOver threshold", () => {
+    const calc = new FlatShippingCalculator(599, 5000);
+    expect(calc.computeShippingCents([makeLine("a", 500)], 6000)).toBe(0);
+  });
+
+  it("returns flat fee when subtotal is just below freeOver threshold", () => {
+    const calc = new FlatShippingCalculator(599, 5000);
+    expect(calc.computeShippingCents([makeLine("a", 500)], 4999)).toBe(599);
+  });
+
+  it("returns flat fee when no freeOver threshold", () => {
+    const calc = new FlatShippingCalculator(599);
+    expect(calc.computeShippingCents([makeLine("a", 500)], 99999)).toBe(599);
+  });
+});
+
+describe("WeightBasedShippingCalculator", () => {
+  describe("constructor validation", () => {
+    it("rejects empty brackets", () => {
+      expect(() => new WeightBasedShippingCalculator([])).toThrow(
+        "at least one weight bracket is required",
+      );
+    });
+
+    it("rejects non-positive upToGrams", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects negative costCents", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects non-integer upToGrams", () => {
+      expect(
+        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
+      ).toThrow(RangeError);
+    });
+
+    it("rejects negative overflowCostCents", () => {
+      expect(
+        () =>
+          new WeightBasedShippingCalculator(
+            [{ upToGrams: 100, costCents: 100 }],
+            -1,
+          ),
+      ).toThrow(RangeError);
+    });
+  });
+
+  const brackets = [
+    { upToGrams: 500, costCents: 300 },
+    { upToGrams: 2000, costCents: 700 },
+    { upToGrams: 5000, costCents: 1200 },
+  ];
+
+  it("returns 0 for empty cart", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([], 1000)).toBe(0);
+  });
+
+  it("returns 0 for zero-weight items", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    const lines: CartLine[] = [
+      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 0 }, quantity: 3 },
+    ];
+    expect(calc.computeShippingCents(lines, 300)).toBe(0);
+  });
+
+  it("selects the correct bracket for weight within first bracket", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 300)], 1000)).toBe(300);
+  });
+
+  it("selects bracket at exact boundary", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
+  });
+
+  it("selects next bracket when just over boundary", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(700);
+  });
+
+  it("selects last bracket at its boundary", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(1200);
+  });
+
+  it("uses overflow cost when weight exceeds all brackets", () => {
+    const calc = new WeightBasedShippingCalculator(brackets, 2500);
+    expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2500);
+  });
+
+  it("defaults overflow to last bracket cost", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(1200);
+  });
+
+  it("sorts brackets regardless of input order", () => {
+    const unsorted = [
+      { upToGrams: 5000, costCents: 1200 },
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 2000, costCents: 700 },
+    ];
+    const calc = new WeightBasedShippingCalculator(unsorted);
+    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
+    expect(calc.computeShippingCents([makeLine("a", 1500)], 1000)).toBe(700);
+  });
+
+  it("sums weight across multiple lines", () => {
+    const calc = new WeightBasedShippingCalculator(brackets);
+    const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
+    // total weight = 300*2 + 500 = 1100 → bracket 2000 → 700
+    expect(calc.computeShippingCents(lines, 1000)).toBe(700);
+  });
+});
+

